import type { CommentChange } from "./diff";

const BREAKPOINT = "\n--> statement-breakpoint\n";

const identifier = (name: string) => `"${name.replace(/"/g, '""')}"`;

const literal = (value: string | null) => (value === null ? "NULL" : `'${value.replace(/'/g, "''")}'`);

// Tables without a schema are left unqualified, the same as the DDL generated by drizzle-kit
const tableName = (change: CommentChange) =>
  change.schema ? `${identifier(change.schema)}.${identifier(change.table)}` : identifier(change.table);

const statement = (change: CommentChange) =>
  change.column === undefined
    ? `COMMENT ON TABLE ${tableName(change)} IS ${literal(change.comment)};`
    : `COMMENT ON COLUMN ${tableName(change)}.${identifier(change.column)} IS ${literal(change.comment)};`;

/** Builds the content of the migration file, with a block of statements per table. */
export function toPostgresSql(changes: CommentChange[]): string {
  const blocks = new Map<string, string[]>();
  for (const change of changes) {
    const name = tableName(change);
    const statements = blocks.get(name) ?? [];
    statements.push(statement(change));
    blocks.set(name, statements);
  }
  const body = [...blocks].map(([name, statements]) => `-- ${name}\n${statements.join(BREAKPOINT)}`);
  return `-- Generated by drizzle-db-comments-generator\n\n${body.join(`${BREAKPOINT}\n`)}\n`;
}
